function lifeJourneys(locale: Locale): string {
  const t = (en:string,ar:string) => copy(locale,[en,ar]);
  return `${pageHeading(t('Life journeys','رحلات الحياة'),t('Related services, gathered around your goal and arranged in a clear order.','خدمات مترابطة مجمعة حول هدفك ومرتبة في مسار واضح.'))}<div class="nq-service-layout"><section class="nq-service-main nq-template-prose"><h2>${t('Prepare your building project','جهّز مشروع البناء')}</h2><p>${t('Move from understanding the requirements to preparing a request and reviewing its details. Each stage provides a clear next action.','انتقل من فهم المتطلبات إلى تجهيز الطلب ومراجعة تفاصيله. تقدم كل مرحلة إجراءً تاليًا واضحًا.')}</p><div class="nq-accordion">${[[t('1. Understand the service','١. تعرف على الخدمة'),t('Check the purpose, requirements, channels and expected steps.','تحقق من الهدف والمتطلبات والقنوات والخطوات المتوقعة.'),'service'],[t('2. Prepare the application','٢. جهّز الطلب'),t('Enter the applicant and site information, then review it.','أدخل معلومات مقدم الطلب والموقع ثم راجعها.'),'form'],[t('3. Share your experience','٣. شارك تجربتك'),t('Tell us what was clear and what could be improved.','أخبرنا بما كان واضحًا وما يمكن تحسينه.'),'rating']].map(([title,body,route],i)=>`<details class="nq-accordion-item" ${i===0?'open':''}><summary class="nq-accordion-trigger">${title}</summary><div class="nq-card-body"><p>${body}</p>${link(route!,t('Open this step','فتح هذه الخطوة'),'secondary')}</div></details>`).join('')}</div></section><aside class="nq-service-aside nq-template-card-aside">${card(t('Journey overview','ملخص الرحلة'),`<dl class="nq-service-metadata"><div><dt>${t('Audience','الفئة المستهدفة')}</dt><dd>${t('Individuals planning a building project','الأفراد الذين يخططون لمشروع بناء')}</dd></div><div><dt>${t('Stages','المراحل')}</dt><dd>${t('3 connected stages','٣ مراحل مترابطة')}</dd></div><div><dt>${t('Scope','نطاق الرحلة')}</dt><dd>${t('A local demonstration, from preparation to confirmation.','تجربة محلية من التحضير حتى التأكيد.')}</dd></div></dl>${link('service',t('Start the journey','بدء الرحلة'),'primary')}`)}</aside></div>`;
}
function sitemap(locale: Locale): string {
  const t = (en:string,ar:string) => copy(locale,[en,ar]);
  return `${pageHeading(t('Sitemap','خريطة الموقع'),t('Find the page you need by its purpose.','اعثر على الصفحة التي تحتاجها بحسب الغرض منها.'))}<div class="nq-template-grid">${[[t('Services and applications','الخدمات والطلبات'),['service','form','life-journeys']],[t('Help and feedback','المساعدة والملاحظات'),['support','contact','faq','chatbot','rating','feedback']],[t('Information and participation','المعلومات والمشاركة'),['about','content','participation','cookies','404']]].map(([label,ids])=>card(label as string,`<ul class="nq-template-link-list">${(ids as string[]).map(id=>`<li>${link(id,titleFor(id,locale))}</li>`).join('')}</ul>`)).join('')}</div>`;
}
function notFound(locale: Locale): string {
  const t = (en:string,ar:string) => copy(locale,[en,ar]);
  return `<section class="nq-empty nq-template-not-found"><p class="nq-template-error-code" aria-hidden="true">404</p><h1 tabindex="-1">${t('We could not find that page','تعذر العثور على الصفحة')}</h1><p>${t('The address may have changed. Explore the service or use the sitemap to continue.','ربما تغير العنوان. استكشف الخدمة أو استخدم خريطة الموقع للمتابعة.')}</p><div class="nq-template-actions">${link('service',t('Explore the service','استكشاف الخدمة'),'primary')}${link('sitemap',t('View sitemap','عرض خريطة الموقع'),'secondary')}</div></section>`;
}

/** Returns null for routes outside this gallery. Root retains hash-route ownership. */
export function renderDgaTemplates(view: string, locale: Locale): string | null {
  if (view !== 'templates' && !view.startsWith('templates/')) return null;
  const route = view.split('/')[1] || 'index';
  const renderers: Record<string,(locale:Locale)=>string> = {index:gallery,service,form:application,contact,support,faq,sitemap,'404':notFound,rating,chatbot,content,cookies,participation,about,feedback: locale=>pageHeading(titleFor('feedback',locale),copy(locale,['Help us understand whether the page answered your question.','ساعدنا في معرفة ما إذا كانت الصفحة قد أجابت عن سؤالك.'])), 'life-journeys':lifeJourneys};
  const render = renderers[route] ?? notFound;
  return `<div class="nq-template" data-dga-template="${escape(route)}" lang="${locale}">${portalHeader(route,locale)}<div class="nq-service-container nq-template-content">${route==='index'?'':breadcrumb(route,locale)}${render(locale)}${feedback(locale)}</div>${portalFooter(locale)}</div>`;
}

/** Only binds template-specific interactions. Generic data-nq widgets belong to enhance(). */
export function bindDgaTemplates(root: HTMLElement, locale: Locale): () => void {
  const scope = root.matches('[data-dga-template]') ? root : root.querySelector<HTMLElement>('[data-dga-template]');
  if (!scope) return () => {};
  const t = (en:string,ar:string) => copy(locale,[en,ar]);
  const controller = new AbortController();
  const listen = (type:string, callback:EventListener) => scope.addEventListener(type,callback,{signal:controller.signal});
  const applicationForm = scope.querySelector<HTMLFormElement>('[data-dga-application]');
  const stageLabels = [t('Applicant and site details','بيانات مقدم الطلب والموقع'),t('Review and declaration','المراجعة والإقرار'),t('Confirmation','التأكيد')];
  function goToStage(index: number, focus = true): void {
    if (!applicationForm) return;
    applicationStage=index;
    applicationForm.dataset.stage=String(index);
    applicationForm.querySelectorAll<HTMLElement>('[data-dga-stage]').forEach((section,i)=>{section.hidden=i!==index; section.querySelectorAll<HTMLFieldSetElement>('fieldset').forEach(fieldset=>fieldset.disabled=i!==index);});
    scope!.querySelectorAll<HTMLElement>('[data-dga-progress] .nq-step').forEach((step,i)=>{step.dataset.state=i<index?'complete':i===index?'current':'upcoming'; if(i===index)step.setAttribute('aria-current','step');else step.removeAttribute('aria-current');});
    const mobile=scope!.querySelector<HTMLElement>('.nq-stepper-mobile');
    if(mobile){mobile.setAttribute('aria-label',t(`Step ${index+1} of 3`,`الخطوة ${number(index+1,locale)} من ${number(3,locale)}`)); const ring=mobile.querySelector<HTMLElement>('.nq-stepper-ring')!;ring.style.setProperty('--nq-step-progress',`${(index+1)/3*100}%`);ring.textContent=`${number(index+1,locale)}/${number(3,locale)}`; mobile.querySelector('strong')!.textContent=stageLabels[index]!;mobile.querySelector('p')!.textContent=index<2?t('Next: ','التالي: ')+stageLabels[index+1]:t('All steps completed','اكتملت جميع الخطوات');}
    if(focus)applicationForm.querySelector<HTMLElement>(`[data-dga-stage="${index}"] h2`)?.focus();
  }
  function updateReview(): void { if(!applicationForm)return; const selected=applicationForm.querySelector<HTMLSelectElement>('[name="city"]');const rows: [string,string][]=[[t('Applicant','مقدم الطلب'),applicationDraft.applicant??''],[t('Email','البريد الإلكتروني'),applicationDraft.email??''],[t('Mobile number','رقم الجوال'),applicationDraft.phone||t('Not provided','لم يُدخل')],[t('City','المدينة'),selected?.selectedOptions[0]?.textContent??''],[t('Site address','عنوان الموقع'),applicationDraft.address??''],[t('Building area (m²)','مساحة البناء (م²)'),applicationDraft.area??''],[t('Project description','وصف المشروع'),applicationDraft.description||t('Not provided','لم يُدخل')],[t('Site plan','مخطط الموقع'),applicationAttachment?.name??t('Not provided','لم يُدخل')]];applicationForm.querySelector('[data-dga-review]')!.innerHTML=rows.map(([label,value])=>`<div><dt>${escape(label)}</dt><dd>${escape(value)}</dd></div>`).join(''); }
  function filterQuestions(): void {
    const query=normalizeSearch(scope!.querySelector<HTMLInputElement>('[data-dga-faq-search]')?.value??'');
    const category=scope!.querySelector<HTMLSelectElement>('[data-dga-faq-category]')?.value??'all';let count=0;
    scope!.querySelectorAll<HTMLDetailsElement>('[data-dga-question]').forEach(item=>{item.hidden=!(normalizeSearch(item.textContent??'').includes(query)&&(category==='all'||category===item.dataset.category));if(!item.hidden)count++;});
    const status=scope!.querySelector('[data-dga-faq-status]');if(status)status.textContent=t(`${count} matching questions`,`${number(count,locale)} أسئلة مطابقة`);
    const empty=scope!.querySelector<HTMLElement>('[data-dga-faq-empty]');if(empty)empty.hidden=count!==0;
  }
  function saveCookies(choice?:boolean):void {
    const form=scope!.querySelector<HTMLFormElement>('[data-dga-cookies]');if(!form)return;
    for(const key of ['analytics','preferences'] as const){const input=form.elements.namedItem(key) as HTMLInputElement;if(choice!==undefined)input.checked=choice;cookiePreferences[key]=input.checked;}
    const status=scope!.querySelector<HTMLElement>('[data-dga-cookie-status]');if(status)status.hidden=false;
  }
  function chat(message:string, topic?:string): void {
    const log=scope!.querySelector<HTMLElement>('[data-dga-messages]');if(!log)return;
    const outgoing=scope!.ownerDocument.createElement('p');outgoing.className='nq-template-message nq-template-message-user';outgoing.textContent=message;log.append(outgoing);
    const query=normalizeSearch(message);const subject=topic??(/contact|email|تواصل|دعم/.test(query)?'contact':/require|متطلب|وثائق/.test(query)?'requirements':'service');
    const response=scope!.ownerDocument.createElement('p');response.className='nq-template-message';response.append(t(subject==='contact'?'You can use the local contact form to explore sending a message.':subject==='requirements'?'Prepare applicant contact information, the city, site address and proposed area.':'Start with the service overview, then open the application when you are ready.',subject==='contact'?'يمكنك استخدام نموذج التواصل المحلي لتجربة إرسال رسالة.':subject==='requirements'?'جهّز معلومات تواصل مقدم الطلب والمدينة وعنوان الموقع والمساحة المقترحة.':'ابدأ بوصف الخدمة ثم افتح الطلب عندما تكون مستعدًا.'));
    const action=scope!.ownerDocument.createElement('a');action.href=`#templates/${subject==='contact'?'contact':'service'}`;action.textContent=t('Open the page','فتح الصفحة');response.append(' ',action);log.append(response);log.scrollTop=log.scrollHeight;
  }
  listen('submit', event=>{
    const form=event.target as HTMLFormElement;
    if(form===applicationForm){event.preventDefault();if(!form.checkValidity()){form.reportValidity();return;}const stage=Number(form.dataset.stage??0);if(stage===0){const values=new FormData(form);for(const key of ['applicant','email','phone','city','address','area','description'])applicationDraft[key]=String(values.get(key)??'');updateReview();goToStage(1);}else if(stage===1)goToStage(2);return;}
    if(form.matches('[data-dga-local]')){event.preventDefault();if(!form.checkValidity()){form.reportValidity();return;}form.hidden=true;const result=form.parentElement?.querySelector<HTMLElement>('[data-dga-success]');if(result){result.hidden=false;result.focus();}return;}
    if(form.matches('[data-dga-cookies]')){event.preventDefault();saveCookies();return;}
    if(form.matches('[data-dga-chat]')){event.preventDefault();const input=form.elements.namedItem('message') as HTMLInputElement;const message=input.value.trim();if(message){chat(message);input.value='';input.focus();}}
  });
  listen('click', event=>{
    const target=(event.target as Element).closest<HTMLElement>('[data-dga-action],[data-dga-scroll]');if(!target||!scope!.contains(target))return;
    if(target.dataset.dgaScroll){event.preventDefault();const destination=scope!.querySelector<HTMLElement>(`#${target.dataset.dgaScroll}`);destination?.scrollIntoView({block:'start'});destination?.focus({preventScroll:true});return;}
    const action=target.dataset.dgaAction;
    if(action==='menu'){const nav=scope!.querySelector<HTMLElement>('#nq-template-navigation')!;const open=nav.dataset.open!=='true';nav.dataset.open=String(open);target.setAttribute('aria-expanded',String(open));}
    else if(action==='application-edit')goToStage(0);
    else if(action==='application-reset'){applicationForm?.reset();applicationDeclared=false;applicationAttachment=null;applicationForm?.querySelector<HTMLInputElement>('[name="declaration"]')?.removeAttribute('checked');const declaration=applicationForm?.querySelector<HTMLInputElement>('[name="declaration"]');if(declaration)declaration.checked=false;for(const key of Object.keys(applicationDraft))delete applicationDraft[key];applicationForm?.querySelectorAll<HTMLInputElement|HTMLTextAreaElement|HTMLSelectElement>('input:not([type=checkbox]),textarea,select').forEach(input=>input.value='');const fileStatus=scope!.querySelector('[data-dga-file-status]');if(fileStatus)fileStatus.textContent='';goToStage(0);}
    else if(action==='faq-clear'){scope!.querySelector<HTMLInputElement>('[data-dga-faq-search]')!.value='';scope!.querySelector<HTMLSelectElement>('[data-dga-faq-category]')!.value='all';filterQuestions();scope!.querySelector<HTMLInputElement>('[data-dga-faq-search]')!.focus();}
    else if(action?.startsWith('feedback-')){const block=target.closest<HTMLElement>('[data-dga-feedback]')!;const form=block.querySelector<HTMLFormElement>('form')!;const result=block.querySelector<HTMLElement>('[data-dga-success]')!;result.hidden=true;form.hidden=false;if(action==='feedback-reset'){form.reset();block.querySelectorAll('[aria-pressed]').forEach(button=>button.setAttribute('aria-pressed','false'));}else{block.querySelectorAll('[aria-pressed]').forEach(button=>button.setAttribute('aria-pressed',String(button===target)));}form.querySelector<HTMLInputElement>('input')?.focus();}
    else if(action==='cookies-reject')saveCookies(false);
    else if(action==='cookies-accept')saveCookies(true);
    else if(action?.startsWith('chat-'))chat(target.textContent??'',action.slice(5));
  });
  listen('input', event=>{const input=event.target as HTMLInputElement;if(input.matches('[data-dga-faq-search]'))filterQuestions();if(input.form===applicationForm&&input.name&&input.type!=='file'&&input.type!=='checkbox')applicationDraft[input.name]=input.value;});
  listen('change', event=>{const input=event.target as HTMLInputElement;if(input.matches('[data-dga-faq-category]'))filterQuestions();if(input.form===applicationForm&&input.name){if(input.name==='declaration')applicationDeclared=input.checked;else if(input.type!=='file')applicationDraft[input.name]=input.value;}if(input.matches('#nq-template-plan')){applicationAttachment=input.files?.[0]??null;const status=scope!.querySelector('[data-dga-file-status]');if(status)status.textContent=applicationAttachment?.name??'';}});
  listen('keydown', event=>{const key=event as KeyboardEvent;if(key.key==='Escape'){const menu=scope!.querySelector<HTMLElement>('[data-dga-action="menu"]');const nav=scope!.querySelector<HTMLElement>('#nq-template-navigation');if(nav?.dataset.open==='true'){nav.dataset.open='false';menu?.setAttribute('aria-expanded','false');menu?.focus();}}});
  if(applicationForm){updateReview();goToStage(applicationStage,false);}
  return ()=>controller.abort();
}
